// NewCbgtCfgMem runs cbgt.NewCfgMem and sets the matching version number we expect for Sync Gateway.
func NewCbgtCfgMem() (*cbgt.CfgMem, error) {
	cfg := cbgt.NewCfgMem()
	cas, err := cfg.Set(cbgt.VERSION_KEY, []byte(SGCbgtMetadataVersion), 0)
	if err != nil {
		return nil, err
	}
	return cfg, nil
}

